new file mode 100644
index 0000000..b535ae4
--- /dev/null
+++ b/internal/hosted/indexer/language.go
@@ -0,0 +1,143 @@
+package indexer
+
+import (
+	"bytes"
+	"context"
+	"errors"
+	"path/filepath"
+	"strings"
+)
+
+type Language string
+
+const (
+	LanguageUnknown    Language = "unknown"
+	LanguageGo         Language = "go"
+	LanguageJavaScript Language = "javascript"
+	LanguageTypeScript Language = "typescript"
+	LanguageTSX        Language = "tsx"
+	LanguagePython     Language = "python"
+	LanguageRuby       Language = "ruby"
+	LanguageRust       Language = "rust"
+	LanguageJava       Language = "java"
+	LanguageC          Language = "c"
+	LanguageCSharp     Language = "csharp"
+	LanguageCPP        Language = "cpp"
+	LanguagePHP        Language = "php"
+)
+
+var extensionLanguages = map[string]Language{
+	".go": LanguageGo, ".js": LanguageJavaScript, ".jsx": LanguageJavaScript,
+	".mjs": LanguageJavaScript, ".cjs": LanguageJavaScript, ".ts": LanguageTypeScript,
+	".mts": LanguageTypeScript, ".cts": LanguageTypeScript, ".tsx": LanguageTSX,
+	".py": LanguagePython, ".rb": LanguageRuby, ".rs": LanguageRust,
+	".java": LanguageJava, ".c": LanguageC, ".h": LanguageC,
+	".cs": LanguageCSharp, ".cc": LanguageCPP, ".cpp": LanguageCPP,
+	".cxx": LanguageCPP, ".hh": LanguageCPP, ".hpp": LanguageCPP, ".php": LanguagePHP,
+}
+
+func DetectLanguage(path string, content []byte) Language {
+	if language := extensionLanguages[strings.ToLower(filepath.Ext(path))]; language != "" {
+		return language
+	}
+	name := strings.ToLower(filepath.Base(path))
+	if name == "gemfile" || name == "rakefile" {
+		return LanguageRuby
+	}
+	firstLine, _, _ := bytes.Cut(content, []byte("\n"))
+	if bytes.HasPrefix(firstLine, []byte("#!")) {
+		line := strings.ToLower(string(firstLine))
+		for marker, language := range map[string]Language{
+			"python": LanguagePython, "ruby": LanguageRuby, "node": LanguageJavaScript, "php": LanguagePHP,
+		} {
+			if strings.Contains(line, marker) {
+				return language
+			}
+		}
+	}
+	return LanguageUnknown
+}
+
+type SyntaxNode struct {
+	Kind      string
+	Name      string
+	StartByte int
+	EndByte   int
+	StartLine int
+	EndLine   int
+}
+
+type TreeSitterParser interface {
+	Parse(context.Context, []byte) ([]SyntaxNode, error)
+}
+
+type ParseResult struct {
+	Language Language
+	Mode     string
+	Reason   string
+	Nodes    []SyntaxNode
+}
+
+type ParserRegistry struct {
+	Parsers     map[Language]TreeSitterParser
+	MaxBytes    int
+	WindowLines int
+	MaxWindows  int
+}
+
+func (r ParserRegistry) Parse(ctx context.Context, path string, content []byte) (ParseResult, error) {
+	maxBytes := r.MaxBytes
+	if maxBytes <= 0 {
+		maxBytes = 1 << 20
+	}
+	if len(content) > maxBytes {
+		return ParseResult{}, errors.New("source exceeds parser byte limit")
+	}
+	if bytes.IndexByte(content, 0) >= 0 {
+		return ParseResult{}, errors.New("binary content is not parsed")
+	}
+	language := DetectLanguage(path, content)
+	parser := r.Parsers[language]
+	if parser != nil {
+		nodes, err := parser.Parse(ctx, content)
+		if err == nil {
+			return ParseResult{Language: language, Mode: "tree-sitter", Nodes: nodes}, nil
+		}
+		if ctx.Err() != nil {
+			return ParseResult{}, ctx.Err()
+		}
+		return ParseResult{Language: language, Mode: "line-window", Reason: "tree-sitter parse failed", Nodes: r.lineWindows(content)}, nil
+	}
+	reason := "language is not supported"
+	if language != LanguageUnknown {
+		reason = "tree-sitter parser is not registered"
+	}
+	return ParseResult{Language: language, Mode: "line-window", Reason: reason, Nodes: r.lineWindows(content)}, nil
+}
+
+func (r ParserRegistry) lineWindows(content []byte) []SyntaxNode {
+	if len(content) == 0 {
+		return nil
+	}
+	window := r.WindowLines
+	if window <= 0 {
+		window = 200
+	}
+	limit := r.MaxWindows
+	if limit <= 0 {
+		limit = 500
+	}
+	lines := bytes.SplitAfter(content, []byte("\n"))
+	nodes := make([]SyntaxNode, 0, min((len(lines)+window-1)/window, limit))
+	offset := 0
+	for start := 0; start < len(lines) && len(nodes) < limit; start += window {
+		end := min(start+window, len(lines))
+		length := 0
+		for _, line := range lines[start:end] {
+			length += len(line)
+		}
+		nodes = append(nodes, SyntaxNode{Kind: "line_window", StartByte: offset, EndByte: offset + length, StartLine: start + 1, EndLine: end})
+		offset += length
+	}
+	return nodes
+}

diff --git a/internal/hosted/indexer/language_test.go b/internal/hosted/indexer/language_test.go
new file mode 100644
index 0000000..21fac47
--- /dev/null
+++ b/internal/hosted/indexer/language_test.go
@@ -0,0 +1,86 @@
+package indexer
+
+import (
+	"context"
+	"errors"
+	"testing"
+)
+
+type parserStub struct{ err error }
+
+func (p parserStub) Parse(_ context.Context, content []byte) ([]SyntaxNode, error) {
+	if p.err != nil {
+		return nil, p.err
+	}
+	return []SyntaxNode{{Kind: "function", Name: "main", StartByte: 0, EndByte: len(content), StartLine: 1, EndLine: 1}}, nil
+}
+
+func TestDetectLanguageUsesExtensionAndShebang(t *testing.T) {
+	for _, test := range []struct {
+		path string
+		body string
+		want Language
+	}{
+		{"main.go", "package main", LanguageGo},
+		{"component.tsx", "export const A = () => null", LanguageTSX},
+		{"tool", "#!/usr/bin/env python3\n", LanguagePython},
+		{"Gemfile", "source 'https://rubygems.org'", LanguageRuby},
+	} {
+		if got := DetectLanguage(test.path, []byte(test.body)); got != test.want {
+			t.Errorf("DetectLanguage(%q) = %q, want %q", test.path, got, test.want)
+		}
+	}
+}
+
+func TestRegistryUsesParserAndExplicitFallback(t *testing.T) {
+	registry := ParserRegistry{Parsers: map[Language]TreeSitterParser{LanguageGo: parserStub{}}}
+	parsed, err := registry.Parse(context.Background(), "main.go", []byte("package main"))
+	if err != nil || parsed.Mode != "tree-sitter" || len(parsed.Nodes) != 1 {
+		t.Fatalf("parsed = %+v, err = %v", parsed, err)
+	}
+
+	registry.Parsers[LanguageGo] = parserStub{err: errors.New("bad tree")}
+	fallback, err := registry.Parse(context.Background(), "main.go", []byte("package main"))
+	if err != nil || fallback.Mode != "line-window" || fallback.Reason == "" {
+		t.Fatalf("fallback = %+v, err = %v", fallback, err)
+	}
+}
+
+func TestRegistryBoundsInputAndFallbackWindows(t *testing.T) {
+	registry := ParserRegistry{MaxBytes: 4, WindowLines: 2, MaxWindows: 2}
+	if _, err := registry.Parse(context.Background(), "a.py", []byte("12345")); err == nil {
+		t.Fatal("expected byte limit error")
+	}
+	registry.MaxBytes = 100
+	parsed, err := registry.Parse(context.Background(), "notes.txt", []byte("1\n2\n3\n4\n5\n"))
+	if err != nil || len(parsed.Nodes) != 2 {
+		t.Fatalf("parsed = %+v, err = %v", parsed, err)
+	}
+}
+
+func TestDefaultRegistryParsesAllInitialLanguages(t *testing.T) {
+	registry := NewParserRegistry()
+	tests := []struct {
+		path string
+		body string
+	}{
+		{"main.go", "package demo\nfunc Run() {}"},
+		{"main.js", "function run() {}"},
+		{"main.ts", "function run(): void {}"},
+		{"view.tsx", "function View() { return <div /> }"},
+		{"main.py", "def run():\n    pass\n"},
+		{"main.rb", "def run\nend\n"},
+		{"main.rs", "fn run() {}"},
+		{"Main.java", "class Main { void run() {} }"},
+		{"main.c", "void run(void) {}"},
+		{"main.cpp", "void run() {}"},
+		{"Main.cs", "class Main { void Run() {} }"},
+		{"main.php", "<?php function run() {}"},
+	}
+	for _, test := range tests {
+		parsed, err := registry.Parse(context.Background(), test.path, []byte(test.body))
+		if err != nil || parsed.Mode != "tree-sitter" || len(parsed.Nodes) == 0 {
+			t.Errorf("%s: parsed = %+v, err = %v", test.path, parsed, err)
+		}
+	}
+}

diff --git a/internal/hosted/indexer/tree_sitter.go b/internal/hosted/indexer/tree_sitter.go
new file mode 100644
index 0000000..8c8994c
--- /dev/null
+++ b/internal/hosted/indexer/tree_sitter.go
@@ -0,0 +1,89 @@
+package indexer
+
+import (
+	"context"
+	"errors"
+
+	treesitter "github.com/tree-sitter/go-tree-sitter"
+	tscsharp "github.com/tree-sitter/tree-sitter-c-sharp/bindings/go"
+	tsc "github.com/tree-sitter/tree-sitter-c/bindings/go"
+	tscpp "github.com/tree-sitter/tree-sitter-cpp/bindings/go"
+	tsgo "github.com/tree-sitter/tree-sitter-go/bindings/go"
+	tsjava "github.com/tree-sitter/tree-sitter-java/bindings/go"
+	tsjavascript "github.com/tree-sitter/tree-sitter-javascript/bindings/go"
+	tsphp "github.com/tree-sitter/tree-sitter-php/bindings/go"
+	tspython "github.com/tree-sitter/tree-sitter-python/bindings/go"
+	tsruby "github.com/tree-sitter/tree-sitter-ruby/bindings/go"
+	tsrust "github.com/tree-sitter/tree-sitter-rust/bindings/go"
+	tstypescript "github.com/tree-sitter/tree-sitter-typescript/bindings/go"
+)
+
+func NewParserRegistry() ParserRegistry {
+	return ParserRegistry{Parsers: map[Language]TreeSitterParser{
+		LanguageGo:         nativeParser{treesitter.NewLanguage(tsgo.Language())},
+		LanguageJavaScript: nativeParser{treesitter.NewLanguage(tsjavascript.Language())},
+		LanguageTypeScript: nativeParser{treesitter.NewLanguage(tstypescript.LanguageTypescript())},
+		LanguageTSX:        nativeParser{treesitter.NewLanguage(tstypescript.LanguageTSX())},
+		LanguagePython:     nativeParser{treesitter.NewLanguage(tspython.Language())},
+		LanguageRuby:       nativeParser{treesitter.NewLanguage(tsruby.Language())},
+		LanguageRust:       nativeParser{treesitter.NewLanguage(tsrust.Language())},
+		LanguageJava:       nativeParser{treesitter.NewLanguage(tsjava.Language())},
+		LanguageC:          nativeParser{treesitter.NewLanguage(tsc.Language())},
+		LanguageCPP:        nativeParser{treesitter.NewLanguage(tscpp.Language())},
+		LanguageCSharp:     nativeParser{treesitter.NewLanguage(tscsharp.Language())},
+		LanguagePHP:        nativeParser{treesitter.NewLanguage(tsphp.LanguagePHP())},
+	}}
+}
+
+type nativeParser struct{ language *treesitter.Language }
+
+func (p nativeParser) Parse(ctx context.Context, content []byte) ([]SyntaxNode, error) {
+	parser := treesitter.NewParser()
+	defer parser.Close()
+	if err := parser.SetLanguage(p.language); err != nil {
+		return nil, err
+	}
+	tree := parser.ParseCtx(ctx, content, nil)
+	if tree == nil {
+		if err := ctx.Err(); err != nil {
+			return nil, err
+		}
+		return nil, errors.New("tree-sitter returned no syntax tree")
+	}
+	defer tree.Close()
+	root := tree.RootNode()
+	nodes := make([]SyntaxNode, 0, root.NamedChildCount())
+	collectDeclarations(root, content, &nodes)
+	if len(nodes) == 0 {
+		for index := uint(0); index < root.NamedChildCount(); index++ {
+			appendSyntaxNode(root.NamedChild(index), "", &nodes)
+		}
+	}
+	return nodes, nil
+}
+
+func collectDeclarations(node *treesitter.Node, content []byte, nodes *[]SyntaxNode) {
+	for index := uint(0); index < node.NamedChildCount(); index++ {
+		child := node.NamedChild(index)
+		if nameNode := child.ChildByFieldName("name"); nameNode != nil {
+			start, end := int(nameNode.StartByte()), int(nameNode.EndByte())
+			name := ""
+			if start >= 0 && end >= start && end <= len(content) && end-start <= 200 {
+				name = string(content[start:end])
+			}
+			appendSyntaxNode(child, name, nodes)
+			continue
+		}
+		collectDeclarations(child, content, nodes)
+	}
+}
+
+func appendSyntaxNode(node *treesitter.Node, name string, nodes *[]SyntaxNode) {
+	if node == nil || node.EndByte() <= node.StartByte() {
+		return
+	}
+	*nodes = append(*nodes, SyntaxNode{
+		Kind: node.Kind(), Name: name, StartByte: int(node.StartByte()), EndByte: int(node.EndByte()),
+		StartLine: int(node.StartPosition().Row) + 1, EndLine: int(node.EndPosition().Row) + 1,
+	})
+}
